-- ---------------------------------------------------------------------------
-- E2 unified AI domain: AI business and runtime tables recreated inside the
-- single `platform` schema under their unified names.
--
-- Generated by scripts/db/generate-unified-migration.py from the frozen AI
-- migrations (services/ai/resources/database/postgres/migrations, V1..V12) plus
-- the E0 table map (mydocs/platform-embedded/03-table-map.json). Do not hand-edit
-- the generated body: change the mapping and regenerate, so the table map and the
-- migration cannot drift apart.
--
-- The AI migrations themselves are never modified: their history stays byte-exact,
-- and this migration is the only forward chain from here on.
-- ---------------------------------------------------------------------------


-- ===== from V1__ai_baseline.sql =====
-- PostgreSQL Schema for Ragent
-- Converted from MySQL schema_table.sql

-- Enable pgvector extension
-- vector is installed in extensions by the superuser bootstrap, outside Flyway.

-- ============================================
-- User & Conversation Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_legacy_user (
    id           VARCHAR(20)  NOT NULL PRIMARY KEY,
    username     VARCHAR(64)  NOT NULL,
    password     VARCHAR(128) NOT NULL,
    role         VARCHAR(32)  NOT NULL,
    avatar       VARCHAR(128),
    create_time  TIMESTAMP  DEFAULT CURRENT_TIMESTAMP,
    update_time  TIMESTAMP  DEFAULT CURRENT_TIMESTAMP,
    deleted      SMALLINT     DEFAULT 0,
    CONSTRAINT uk_user_username UNIQUE (username)
);
COMMENT ON TABLE platform.ai_legacy_user IS '系统用户表';
COMMENT ON COLUMN platform.ai_legacy_user.id IS '主键ID';
COMMENT ON COLUMN platform.ai_legacy_user.username IS '用户名，唯一';
COMMENT ON COLUMN platform.ai_legacy_user.password IS '密码';
COMMENT ON COLUMN platform.ai_legacy_user.role IS '角色：admin/user';
COMMENT ON COLUMN platform.ai_legacy_user.avatar IS '用户头像';
COMMENT ON COLUMN platform.ai_legacy_user.create_time IS '创建时间';
COMMENT ON COLUMN platform.ai_legacy_user.update_time IS '更新时间';
COMMENT ON COLUMN platform.ai_legacy_user.deleted IS '是否删除 0：正常 1：删除';

CREATE TABLE IF NOT EXISTS platform.ai_conversation (
    id              VARCHAR(20) NOT NULL PRIMARY KEY,
    conversation_id VARCHAR(20) NOT NULL,
    user_id         VARCHAR(20) NOT NULL,
    title           VARCHAR(128) NOT NULL,
    last_time       TIMESTAMP,
    create_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted         SMALLINT    DEFAULT 0,
    CONSTRAINT uk_conversation_user UNIQUE (conversation_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_user_time ON platform.ai_conversation (user_id, last_time);
COMMENT ON TABLE platform.ai_conversation IS '会话列表';
COMMENT ON COLUMN platform.ai_conversation.id IS '主键ID';
COMMENT ON COLUMN platform.ai_conversation.conversation_id IS '会话ID';
COMMENT ON COLUMN platform.ai_conversation.user_id IS '用户ID';
COMMENT ON COLUMN platform.ai_conversation.title IS '会话名称';
COMMENT ON COLUMN platform.ai_conversation.last_time IS '最近消息时间';
COMMENT ON COLUMN platform.ai_conversation.create_time IS '创建时间';
COMMENT ON COLUMN platform.ai_conversation.update_time IS '更新时间';
COMMENT ON COLUMN platform.ai_conversation.deleted IS '是否删除 0：正常 1：删除';

CREATE TABLE IF NOT EXISTS platform.ai_conversation_summary (
    id              VARCHAR(20)      NOT NULL PRIMARY KEY,
    conversation_id VARCHAR(20) NOT NULL,
    user_id         VARCHAR(20) NOT NULL,
    last_message_id VARCHAR(20) NOT NULL,
    content         TEXT        NOT NULL,
    create_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted         SMALLINT    DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_conv_user ON platform.ai_conversation_summary (conversation_id, user_id);
COMMENT ON TABLE platform.ai_conversation_summary IS '会话摘要表（与消息表分离存储）';

CREATE TABLE IF NOT EXISTS platform.ai_message (
    id                VARCHAR(20)      NOT NULL PRIMARY KEY,
    conversation_id   VARCHAR(20) NOT NULL,
    user_id           VARCHAR(20) NOT NULL,
    role              VARCHAR(16) NOT NULL,
    content           TEXT        NOT NULL,
    thinking_content  TEXT,
    thinking_duration INTEGER,
    sources              JSONB,
    recommended_questions JSONB,
    retrieved_chunks  JSONB,
    reply_to_message_id VARCHAR(20),
    message_status    VARCHAR(16) NOT NULL DEFAULT 'NORMAL',
    create_time       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted           SMALLINT    DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_conversation_user_time ON platform.ai_message (conversation_id, user_id, create_time);
CREATE INDEX IF NOT EXISTS idx_conversation_summary ON platform.ai_message (conversation_id, user_id, create_time);
COMMENT ON TABLE platform.ai_message IS '会话消息记录表';

CREATE TABLE IF NOT EXISTS platform.ai_message_feedback (
    id              VARCHAR(20)       NOT NULL PRIMARY KEY,
    message_id      VARCHAR(20)       NOT NULL,
    conversation_id VARCHAR(20)  NOT NULL,
    user_id         VARCHAR(20)  NOT NULL,
    vote            SMALLINT     NOT NULL,
    reason          VARCHAR(255),
    comment         VARCHAR(1024),
    create_time     TIMESTAMP  NOT NULL,
    update_time     TIMESTAMP  NOT NULL,
    deleted         SMALLINT     NOT NULL DEFAULT 0,
    CONSTRAINT uk_msg_user UNIQUE (message_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_conversation_id ON platform.ai_message_feedback (conversation_id);
CREATE INDEX IF NOT EXISTS idx_user_id ON platform.ai_message_feedback (user_id);
COMMENT ON TABLE platform.ai_message_feedback IS '会话消息反馈表';

CREATE TABLE IF NOT EXISTS platform.ai_sample_question (
    id          VARCHAR(20)        NOT NULL PRIMARY KEY,
    title       VARCHAR(64),
    description VARCHAR(255),
    question    VARCHAR(255) NOT NULL,
    create_time TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT      DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_sample_question_deleted ON platform.ai_sample_question (deleted);
COMMENT ON TABLE platform.ai_sample_question IS '示例问题表';

-- ============================================
-- Business Change Audit Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_biz_change_log (
    id               VARCHAR(20)  NOT NULL PRIMARY KEY,
    biz_type         VARCHAR(64)  NOT NULL,
    biz_id           VARCHAR(64)  NOT NULL,
    operation_type   VARCHAR(32)  NOT NULL,
    action_desc      VARCHAR(512),
    before_snapshot  JSONB,
    after_snapshot   JSONB,
    change_diff      JSONB,
    operator_id      VARCHAR(64),
    operator_name    VARCHAR(128),
    operator_role    VARCHAR(64),
    success          BOOLEAN      NOT NULL DEFAULT TRUE,
    error_message    TEXT,
    class_name       VARCHAR(255),
    method_name      VARCHAR(255),
    ip               VARCHAR(64),
    user_agent       VARCHAR(512),
    create_time      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_biz_change_log_biz ON platform.ai_biz_change_log (biz_type, biz_id);
CREATE INDEX IF NOT EXISTS idx_biz_change_log_time ON platform.ai_biz_change_log (create_time);
CREATE INDEX IF NOT EXISTS idx_biz_change_log_operator ON platform.ai_biz_change_log (operator_id);
COMMENT ON TABLE platform.ai_biz_change_log IS '业务数据变更审计日志表';
COMMENT ON COLUMN platform.ai_biz_change_log.biz_type IS '业务对象类型';
COMMENT ON COLUMN platform.ai_biz_change_log.biz_id IS '业务对象主键';
COMMENT ON COLUMN platform.ai_biz_change_log.operation_type IS '操作类型';
COMMENT ON COLUMN platform.ai_biz_change_log.action_desc IS '操作描述';
COMMENT ON COLUMN platform.ai_biz_change_log.before_snapshot IS '变更前快照';
COMMENT ON COLUMN platform.ai_biz_change_log.after_snapshot IS '变更后快照';
COMMENT ON COLUMN platform.ai_biz_change_log.change_diff IS '变更差异';
COMMENT ON COLUMN platform.ai_biz_change_log.operator_id IS '操作人ID';
COMMENT ON COLUMN platform.ai_biz_change_log.operator_name IS '操作人名称';
COMMENT ON COLUMN platform.ai_biz_change_log.operator_role IS '操作人角色';
COMMENT ON COLUMN platform.ai_biz_change_log.success IS '是否成功';
COMMENT ON COLUMN platform.ai_biz_change_log.error_message IS '失败信息';
COMMENT ON COLUMN platform.ai_biz_change_log.class_name IS '触发类名';
COMMENT ON COLUMN platform.ai_biz_change_log.method_name IS '触发方法名';
COMMENT ON COLUMN platform.ai_biz_change_log.ip IS '来源IP';
COMMENT ON COLUMN platform.ai_biz_change_log.user_agent IS 'User-Agent';
COMMENT ON COLUMN platform.ai_biz_change_log.create_time IS '创建时间';

-- ============================================
-- Knowledge Base Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_base (
    id              VARCHAR(20)       NOT NULL PRIMARY KEY,
    name            VARCHAR(128) NOT NULL,
    embedding_model VARCHAR(64)  NOT NULL,
    collection_name VARCHAR(64) NOT NULL,
    created_by      VARCHAR(20)  NOT NULL,
    updated_by      VARCHAR(20),
    create_time     TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted         SMALLINT     NOT NULL DEFAULT 0,
    CONSTRAINT uk_collection_name UNIQUE (collection_name)
);
CREATE INDEX IF NOT EXISTS idx_kb_name ON platform.ai_knowledge_base (name);
COMMENT ON TABLE platform.ai_knowledge_base IS '知识库表';

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_document (
    id               VARCHAR(20)        NOT NULL PRIMARY KEY,
    kb_id            VARCHAR(20)        NOT NULL,
    doc_name         VARCHAR(256)  NOT NULL,
    enabled          SMALLINT      NOT NULL DEFAULT 1,
    chunk_count      INTEGER       DEFAULT 0,
    file_url         VARCHAR(1024) NOT NULL,
    file_type        VARCHAR(16)   NOT NULL,
    mime_type        VARCHAR(128),
    file_size        BIGINT,
    process_mode     VARCHAR(16)   DEFAULT 'chunk',
    status           VARCHAR(16)   NOT NULL DEFAULT 'pending',
    source_type      VARCHAR(16),
    source_location  VARCHAR(1024),
    schedule_enabled SMALLINT,
    schedule_cron    VARCHAR(64),
    ingestion_spec   JSONB,
    pipeline_id      VARCHAR(20),
    created_by       VARCHAR(20)   NOT NULL,
    updated_by       VARCHAR(20),
    create_time      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted          SMALLINT      NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_kb_id ON platform.ai_knowledge_document (kb_id);
COMMENT ON TABLE platform.ai_knowledge_document IS '知识库文档表';

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_chunk (
    id             VARCHAR(20)      NOT NULL PRIMARY KEY,
    kb_id          VARCHAR(20)      NOT NULL,
    doc_id         VARCHAR(20)      NOT NULL,
    chunk_index    INTEGER     NOT NULL,
    content        TEXT        NOT NULL,
    content_hash   VARCHAR(64),
    char_count     INTEGER,
    token_count    INTEGER,
    embedding_text TEXT,
    enabled        SMALLINT    NOT NULL DEFAULT 1,
    created_by     VARCHAR(20) NOT NULL,
    updated_by     VARCHAR(20),
    create_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted        SMALLINT    NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_doc_id ON platform.ai_knowledge_chunk (doc_id);
COMMENT ON TABLE platform.ai_knowledge_chunk IS '知识库文档分块表';

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_document_chunk_log (
    id                 VARCHAR(20)      NOT NULL PRIMARY KEY,
    doc_id             VARCHAR(20)      NOT NULL,
    status             VARCHAR(16)      NOT NULL,
    process_mode       VARCHAR(16),
    parse_profile      VARCHAR(16),
    pipeline_id        VARCHAR(20),
    extract_duration   BIGINT,
    chunk_duration     BIGINT,
    embed_duration     BIGINT,
    persist_duration   BIGINT,
    total_duration     BIGINT,
    chunk_count        INTEGER,
    error_message      TEXT,
    start_time         TIMESTAMP,
    end_time           TIMESTAMP,
    create_time        TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time        TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_doc_id_log ON platform.ai_knowledge_document_chunk_log (doc_id);
COMMENT ON TABLE platform.ai_knowledge_document_chunk_log IS '知识库文档分块日志表';

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_document_schedule (
    id                VARCHAR(20)       NOT NULL PRIMARY KEY,
    doc_id            VARCHAR(20)       NOT NULL,
    kb_id             VARCHAR(20)       NOT NULL,
    cron_expr         VARCHAR(64),
    enabled           SMALLINT     DEFAULT 0,
    next_run_time     TIMESTAMP,
    last_run_time     TIMESTAMP,
    last_success_time TIMESTAMP,
    last_status       VARCHAR(16),
    last_error        VARCHAR(512),
    last_etag         VARCHAR(256),
    last_modified     VARCHAR(256),
    last_content_hash VARCHAR(128),
    lock_owner        VARCHAR(128),
    lock_until        TIMESTAMP,
    create_time       TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time       TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_doc_id UNIQUE (doc_id)
);
CREATE INDEX IF NOT EXISTS idx_next_run ON platform.ai_knowledge_document_schedule (next_run_time);
CREATE INDEX IF NOT EXISTS idx_lock_until ON platform.ai_knowledge_document_schedule (lock_until);
COMMENT ON TABLE platform.ai_knowledge_document_schedule IS '知识库文档定时刷新任务表';

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_document_schedule_exec (
    id            VARCHAR(20)       NOT NULL PRIMARY KEY,
    schedule_id   VARCHAR(20)       NOT NULL,
    doc_id        VARCHAR(20)       NOT NULL,
    kb_id         VARCHAR(20)       NOT NULL,
    status        VARCHAR(16)  NOT NULL,
    message       VARCHAR(512),
    start_time    TIMESTAMP,
    end_time      TIMESTAMP,
    file_name     VARCHAR(512),
    file_size     BIGINT,
    content_hash  VARCHAR(128),
    etag          VARCHAR(256),
    last_modified VARCHAR(256),
    create_time   TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_schedule_time ON platform.ai_knowledge_document_schedule_exec (schedule_id, start_time);
CREATE INDEX IF NOT EXISTS idx_doc_id_exec ON platform.ai_knowledge_document_schedule_exec (doc_id);
COMMENT ON TABLE platform.ai_knowledge_document_schedule_exec IS '知识库文档定时刷新执行记录';

-- ============================================
-- RAG Intent & Query Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_intent_node (
    id                    VARCHAR(20)       NOT NULL PRIMARY KEY,
    kb_id                 VARCHAR(20),
    intent_code           VARCHAR(64)  NOT NULL,
    name                  VARCHAR(64)  NOT NULL,
    level                 SMALLINT     NOT NULL,
    parent_code           VARCHAR(64),
    description           VARCHAR(512),
    examples              TEXT,
    collection_name       VARCHAR(128),
    collection_names      JSONB        NOT NULL DEFAULT '[]'::jsonb,
    top_k                 INTEGER,
    mcp_tool_id           VARCHAR(128),
    require_confirm       SMALLINT     NOT NULL DEFAULT 0,
    kind                  SMALLINT     NOT NULL DEFAULT 0,
    prompt_snippet        TEXT,
    prompt_template       TEXT,
    sort_order            INTEGER      NOT NULL DEFAULT 0,
    enabled               SMALLINT     NOT NULL DEFAULT 1,
    create_by             VARCHAR(20),
    update_by             VARCHAR(20),
    create_time           TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time           TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted               SMALLINT     NOT NULL DEFAULT 0
);
COMMENT ON TABLE platform.ai_intent_node IS '意图树节点配置表';

CREATE TABLE IF NOT EXISTS platform.ai_query_term_mapping (
    id          VARCHAR(20)       NOT NULL PRIMARY KEY,
    domain      VARCHAR(64),
    source_term VARCHAR(128) NOT NULL,
    target_term VARCHAR(128) NOT NULL,
    match_type  SMALLINT     NOT NULL DEFAULT 1,
    priority    INTEGER      NOT NULL DEFAULT 100,
    enabled     SMALLINT     NOT NULL DEFAULT 1,
    remark      VARCHAR(255),
    create_by   VARCHAR(20),
    update_by   VARCHAR(20),
    create_time TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT     NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_domain ON platform.ai_query_term_mapping (domain);
CREATE INDEX IF NOT EXISTS idx_source ON platform.ai_query_term_mapping (source_term);
COMMENT ON TABLE platform.ai_query_term_mapping IS '关键词归一化映射表';

CREATE TABLE IF NOT EXISTS platform.ai_rag_trace_run (
    id              VARCHAR(20)           NOT NULL PRIMARY KEY,
    trace_id        VARCHAR(64)      NOT NULL,
    trace_name      VARCHAR(128),
    entry_method    VARCHAR(256),
    conversation_id VARCHAR(20),
    task_id         VARCHAR(20),
    user_id         VARCHAR(20),
    status          VARCHAR(16)      NOT NULL DEFAULT 'RUNNING',
    error_message   VARCHAR(1000),
    start_time      TIMESTAMP(3),
    end_time        TIMESTAMP(3),
    duration_ms     BIGINT,
    extra_data      TEXT,
    create_time     TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
    deleted         SMALLINT         DEFAULT 0,
    CONSTRAINT uk_run_id UNIQUE (trace_id)
);
CREATE INDEX IF NOT EXISTS idx_task_id ON platform.ai_rag_trace_run (task_id);
CREATE INDEX IF NOT EXISTS idx_user_id_trace ON platform.ai_rag_trace_run (user_id);
COMMENT ON TABLE platform.ai_rag_trace_run IS 'Trace 运行记录表';

CREATE TABLE IF NOT EXISTS platform.ai_rag_trace_node (
    id             VARCHAR(20)           NOT NULL PRIMARY KEY,
    trace_id       VARCHAR(20)      NOT NULL,
    node_id        VARCHAR(20)      NOT NULL,
    parent_node_id VARCHAR(20),
    depth          INTEGER          DEFAULT 0,
    node_type      VARCHAR(16),
    node_name      VARCHAR(128),
    class_name     VARCHAR(256),
    method_name    VARCHAR(128),
    status         VARCHAR(16)      NOT NULL DEFAULT 'RUNNING',
    error_message  VARCHAR(1000),
    start_time     TIMESTAMP(3),
    end_time       TIMESTAMP(3),
    duration_ms    BIGINT,
    extra_data     TEXT,
    create_time    TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
    update_time    TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
    deleted        SMALLINT         DEFAULT 0,
    CONSTRAINT uk_run_node UNIQUE (trace_id, node_id)
);
COMMENT ON TABLE platform.ai_rag_trace_node IS 'Trace 节点记录表';

-- ============================================
-- Agent Profile Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_agent_profile (
    id          VARCHAR(20)  NOT NULL PRIMARY KEY,
    name        VARCHAR(64)  NOT NULL,
    description VARCHAR(512),
    avatar      VARCHAR(32),
    builtin     SMALLINT     NOT NULL DEFAULT 0,
    active      SMALLINT     NOT NULL DEFAULT 0,
    create_by   VARCHAR(20),
    update_by   VARCHAR(20),
    create_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT     NOT NULL DEFAULT 0,
    CONSTRAINT uk_agent_name UNIQUE (name)
);
CREATE INDEX IF NOT EXISTS idx_agent_active ON platform.ai_agent_profile (active);
COMMENT ON TABLE platform.ai_agent_profile IS '智能体人设配置表';

CREATE TABLE IF NOT EXISTS platform.ai_agent_prompt (
    id          VARCHAR(20)  NOT NULL PRIMARY KEY,
    agent_id    VARCHAR(20)  NOT NULL,
    slot_key    VARCHAR(64)  NOT NULL,
    content     TEXT,
    create_by   VARCHAR(20),
    update_by   VARCHAR(20),
    create_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT     NOT NULL DEFAULT 0,
    CONSTRAINT uk_agent_slot UNIQUE (agent_id, slot_key)
);
CREATE INDEX IF NOT EXISTS idx_agent_prompt_agent ON platform.ai_agent_prompt (agent_id);
COMMENT ON TABLE platform.ai_agent_prompt IS '智能体提示词槽位表';

CREATE TABLE IF NOT EXISTS platform.ai_agent_skill (
    id          VARCHAR(20)  NOT NULL PRIMARY KEY,
    skill_code  VARCHAR(64)  NOT NULL,
    name        VARCHAR(64)  NOT NULL,
    description VARCHAR(512) NOT NULL,
    content     TEXT         NOT NULL,
    tool_ids    JSONB        NOT NULL DEFAULT '[]'::jsonb,
    sort_order  INTEGER      NOT NULL DEFAULT 0,
    enabled     SMALLINT     NOT NULL DEFAULT 1,
    create_by   VARCHAR(20),
    update_by   VARCHAR(20),
    create_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT     NOT NULL DEFAULT 0
);
-- 逻辑删除后 skill_code 应可重新占用，唯一性只约束未删除的行
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_skill_code ON platform.ai_agent_skill (skill_code) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_agent_skill_enabled ON platform.ai_agent_skill (enabled, deleted);
COMMENT ON TABLE platform.ai_agent_skill IS '智能体技能表';

-- ============================================
-- Agent Engine Tables (v2 ReAct，与 workflow 会话两套分立)
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_agent_conversation (
    id              VARCHAR(20) NOT NULL PRIMARY KEY,
    conversation_id VARCHAR(20) NOT NULL,
    user_id         VARCHAR(20) NOT NULL,
    title           VARCHAR(128) NOT NULL,
    last_time       TIMESTAMP,
    create_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted         SMALLINT    DEFAULT 0
);
-- 部分唯一索引：逻辑删的旧行不再占用唯一键，否则删除后同 ID 重开会话必撞约束
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_conversation_user ON platform.ai_agent_conversation (conversation_id, user_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_agent_conv_user_time ON platform.ai_agent_conversation (user_id, last_time);
COMMENT ON TABLE platform.ai_agent_conversation IS 'Agent 会话列表';

CREATE TABLE IF NOT EXISTS platform.ai_agent_message (
    id                  VARCHAR(20) NOT NULL PRIMARY KEY,
    conversation_id     VARCHAR(20) NOT NULL,
    user_id             VARCHAR(20) NOT NULL,
    role                VARCHAR(16) NOT NULL,
    content             TEXT,
    thinking_content    TEXT,
    blocks              JSONB,
    reply_to_message_id VARCHAR(20),
    message_status      VARCHAR(32) NOT NULL DEFAULT 'NORMAL',
    duration_ms         BIGINT,
    create_time         TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time         TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted             SMALLINT    DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_agent_msg_conv ON platform.ai_agent_message (conversation_id, user_id, create_time);
-- 长期记忆按用户跨会话取待处理消息，按 id 升序
CREATE INDEX IF NOT EXISTS idx_agent_msg_user ON platform.ai_agent_message (user_id, id);
COMMENT ON TABLE platform.ai_agent_message IS 'Agent 消息记录';

CREATE TABLE IF NOT EXISTS platform.ai_agent_state (
    user_id     VARCHAR(64) NOT NULL,
    session_id  VARCHAR(64) NOT NULL,
    state_key   VARCHAR(64) NOT NULL,
    payload     JSONB,
    create_time TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, session_id, state_key)
);
COMMENT ON TABLE platform.ai_agent_state IS 'AgentScope 工作状态存储，payload 为框架自有编码的不透明 JSON';

CREATE TABLE IF NOT EXISTS platform.ai_agent_context_compaction (
    id                   VARCHAR(20) NOT NULL PRIMARY KEY,
    user_id              VARCHAR(20) NOT NULL,
    conversation_id      VARCHAR(20) NOT NULL,
    generation           INTEGER     NOT NULL,
    summary              TEXT,
    material_msg_count   INTEGER     NOT NULL,
    material_chars       INTEGER     NOT NULL,
    summary_chars        INTEGER     NOT NULL,
    context_chars_before INTEGER     NOT NULL,
    context_chars_after  INTEGER     NOT NULL,
    create_time          TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_agent_compaction_conv ON platform.ai_agent_context_compaction (conversation_id, user_id, create_time);
COMMENT ON TABLE platform.ai_agent_context_compaction IS 'Agent 上下文压缩事件，追加型审计日志，应用侧无读路径';

CREATE TABLE IF NOT EXISTS platform.ai_agent_memory (
    id            VARCHAR(20)  NOT NULL PRIMARY KEY,
    user_id       VARCHAR(20)  NOT NULL,
    content       VARCHAR(500) NOT NULL,
    source_type   VARCHAR(16)  NOT NULL,
    invalid_at    TIMESTAMP,
    superseded_by VARCHAR(20),
    create_time   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- 部分索引：读路径只查 ACTIVE，失效行不进索引
CREATE INDEX IF NOT EXISTS idx_agent_memory_active ON platform.ai_agent_memory (user_id) WHERE invalid_at IS NULL;
COMMENT ON TABLE platform.ai_agent_memory IS 'Agent长期记忆事实表';

CREATE TABLE IF NOT EXISTS platform.ai_agent_memory_extraction (
    id              VARCHAR(20) NOT NULL PRIMARY KEY,
    user_id         VARCHAR(20) NOT NULL,
    conversation_id VARCHAR(20) NOT NULL,
    from_message_id VARCHAR(20) NOT NULL,
    to_message_id   VARCHAR(20) NOT NULL,
    status          VARCHAR(16) NOT NULL,
    trigger_type    VARCHAR(16) NOT NULL,
    decision_count  INTEGER     NOT NULL DEFAULT 0,
    attempt_count   INTEGER     NOT NULL DEFAULT 1,
    create_time     TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    settle_time     TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_agent_memory_extraction_user ON platform.ai_agent_memory_extraction (user_id, to_message_id);
-- 部分唯一索引即分布式 claim：同一用户同时只允许一次在飞抽取，记忆只有一份，消费顺序必须是说话先后
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_memory_extraction_processing
    ON platform.ai_agent_memory_extraction (user_id) WHERE status = 'PROCESSING';
COMMENT ON TABLE platform.ai_agent_memory_extraction IS 'Agent长期记忆抽取台账';

CREATE TABLE IF NOT EXISTS platform.ai_agent_memory_control (
    user_id     VARCHAR(20) NOT NULL PRIMARY KEY,
    revision    BIGINT      NOT NULL DEFAULT 0,
    create_time TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE platform.ai_agent_memory_control IS 'Agent长期记忆控制面';

-- ============================================
-- Ingestion Pipeline Tables
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_ingestion_pipeline (
    id          VARCHAR(20)      NOT NULL PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    description TEXT,
    created_by  VARCHAR(20) DEFAULT '',
    updated_by  VARCHAR(20) DEFAULT '',
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     SMALLINT    NOT NULL DEFAULT 0,
    CONSTRAINT uk_ingestion_pipeline_name UNIQUE (name, deleted)
);
COMMENT ON TABLE platform.ai_ingestion_pipeline IS '摄取流水线表';

CREATE TABLE IF NOT EXISTS platform.ai_ingestion_pipeline_node (
    id             VARCHAR(20)      NOT NULL PRIMARY KEY,
    pipeline_id    VARCHAR(20)      NOT NULL,
    node_id        VARCHAR(20) NOT NULL,
    node_type      VARCHAR(16) NOT NULL,
    next_node_id   VARCHAR(20),
    settings_json  JSONB,
    condition_json JSONB,
    created_by     VARCHAR(20) DEFAULT '',
    updated_by     VARCHAR(20) DEFAULT '',
    create_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted        SMALLINT    NOT NULL DEFAULT 0,
    CONSTRAINT uk_ingestion_pipeline_node UNIQUE (pipeline_id, node_id, deleted)
);
CREATE INDEX IF NOT EXISTS idx_ingestion_pipeline_node_pipeline ON platform.ai_ingestion_pipeline_node (pipeline_id);
COMMENT ON TABLE platform.ai_ingestion_pipeline_node IS '摄取流水线节点表';

CREATE TABLE IF NOT EXISTS platform.ai_ingestion_task (
    id               VARCHAR(20)      NOT NULL PRIMARY KEY,
    pipeline_id      VARCHAR(20)      NOT NULL,
    source_type      VARCHAR(20) NOT NULL,
    source_location  TEXT,
    source_file_name VARCHAR(255),
    status           VARCHAR(16) NOT NULL,
    chunk_count      INTEGER     DEFAULT 0,
    error_message    TEXT,
    logs_json        JSONB,
    metadata_json    JSONB,
    started_at       TIMESTAMP,
    completed_at     TIMESTAMP,
    created_by       VARCHAR(20) DEFAULT '',
    updated_by       VARCHAR(20) DEFAULT '',
    create_time      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted          SMALLINT    NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_ingestion_task_pipeline ON platform.ai_ingestion_task (pipeline_id);
CREATE INDEX IF NOT EXISTS idx_ingestion_task_status ON platform.ai_ingestion_task (status);
COMMENT ON TABLE platform.ai_ingestion_task IS '摄取任务表';

CREATE TABLE IF NOT EXISTS platform.ai_ingestion_task_node (
    id            VARCHAR(20)      NOT NULL PRIMARY KEY,
    task_id       VARCHAR(20)      NOT NULL,
    pipeline_id   VARCHAR(20)      NOT NULL,
    node_id       VARCHAR(20) NOT NULL,
    node_type     VARCHAR(16) NOT NULL,
    node_order    INTEGER     NOT NULL DEFAULT 0,
    status        VARCHAR(16) NOT NULL,
    duration_ms   BIGINT      NOT NULL DEFAULT 0,
    message       TEXT,
    error_message TEXT,
    output_json   TEXT,
    create_time   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted       SMALLINT    NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_ingestion_task_node_task ON platform.ai_ingestion_task_node (task_id);
CREATE INDEX IF NOT EXISTS idx_ingestion_task_node_pipeline ON platform.ai_ingestion_task_node (pipeline_id);
CREATE INDEX IF NOT EXISTS idx_ingestion_task_node_status ON platform.ai_ingestion_task_node (status);
COMMENT ON TABLE platform.ai_ingestion_task_node IS '摄取任务节点表';

-- ============================================
-- Vector Storage Table (pgvector)
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_knowledge_vector (
    id              VARCHAR(20) PRIMARY KEY,
    collection_name VARCHAR(64) NOT NULL,
    content         TEXT,
    metadata        JSONB,
    embedding       vector(1536)
);

CREATE INDEX IF NOT EXISTS idx_kv_collection_name ON platform.ai_knowledge_vector (collection_name);
CREATE INDEX IF NOT EXISTS idx_kv_metadata ON platform.ai_knowledge_vector USING gin(metadata);
CREATE INDEX IF NOT EXISTS idx_kv_embedding ON platform.ai_knowledge_vector USING hnsw (embedding vector_cosine_ops);
COMMENT ON TABLE platform.ai_knowledge_vector IS '知识库向量存储表';
COMMENT ON COLUMN platform.ai_knowledge_vector.id IS '分块ID';
COMMENT ON COLUMN platform.ai_knowledge_vector.collection_name IS '知识库Collection';
COMMENT ON COLUMN platform.ai_knowledge_vector.content IS '分块文本内容';
COMMENT ON COLUMN platform.ai_knowledge_vector.metadata IS '元数据';
COMMENT ON COLUMN platform.ai_knowledge_vector.embedding IS '向量';

