-- ===== from V5__tenant_state_and_run_refs.sql =====
-- V5：state/memory 复合约束 + 正式 run/event/outbox/usage/replay 归属结构。
--
-- state 与 memory 的可重复业务标识在租户内可重复（同名 user、同 session_id），
-- 键必须含租户/成员，否则两个租户命中同一行、删除互相命中。本迁移换键，
-- 并保留 user_id 列为展示/legacy 引用（member_id 才是权威主体引用，不截断）。
--
-- 正式 run/event/outbox/usage/replay 表在本迁移建立（正式命名，区别于
-- experiments/p04 的实验表）：事件读取按 (tenant, run, seq)，不能裸 eventId；
-- replay 是委托 jti 的正式消费账。P1 只做只读 repository 与 replay 消费，
-- run 提交/Worker/SSE/恢复/审批保持关闭。
--
-- 归属守卫与 V4 同一契约：未知归属行明确拒绝，不默认、不删除。

-- ============================================
-- 1. 归属守卫（state/memory 三表换键前的拒绝检查）
-- ============================================

DO $$
DECLARE
    unknown_state bigint; unknown_control bigint; unknown_extraction bigint; msg text;
BEGIN
    SELECT count(*) INTO unknown_state FROM ai_agent_state
        WHERE tenant_id IS NULL OR member_id IS NULL;
    SELECT count(*) INTO unknown_control FROM ai_agent_memory_control
        WHERE tenant_id IS NULL OR member_id IS NULL;
    SELECT count(*) INTO unknown_extraction FROM ai_agent_memory_extraction
        WHERE tenant_id IS NULL OR member_id IS NULL;
    IF unknown_state > 0 OR unknown_control > 0 OR unknown_extraction > 0 THEN
        msg := 'P1 tenant attribution guard: rows with unknown attribution refused '
            || 'before state/memory key change (ai_agent_state=' || unknown_state
            || ', ai_agent_memory_control=' || unknown_control
            || ', ai_agent_memory_extraction=' || unknown_extraction
            || '); resolve attribution via the C6 process; no rows were modified or deleted';
        RAISE EXCEPTION USING ERRCODE = 'P1001', MESSAGE = msg;
    END IF;
END $$;

-- ============================================
-- 2. ai_agent_state：主键换为 (tenant_id, member_id, session_id, state_key)
-- ============================================

ALTER TABLE platform.ai_agent_state ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE platform.ai_agent_state ALTER COLUMN member_id  SET NOT NULL;
ALTER TABLE platform.ai_agent_state ADD CONSTRAINT ck_t_agent_state_tenant CHECK (btrim(tenant_id) <> '');

ALTER TABLE platform.ai_agent_state DROP CONSTRAINT ai_agent_state_pkey;
ALTER TABLE platform.ai_agent_state ADD CONSTRAINT pk_t_agent_state
    PRIMARY KEY (tenant_id, member_id, session_id, state_key);
-- user_id 不再参与键：它只是 20 位 legacy 展示引用，权威主体引用是 member_id。

-- ============================================
-- 3. ai_agent_memory_control：主键换为 (tenant_id, member_id)
-- ============================================

ALTER TABLE platform.ai_agent_memory_control ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE platform.ai_agent_memory_control ALTER COLUMN member_id  SET NOT NULL;
ALTER TABLE platform.ai_agent_memory_control ADD CONSTRAINT ck_t_agent_memory_control_tenant CHECK (btrim(tenant_id) <> '');

ALTER TABLE platform.ai_agent_memory_control DROP CONSTRAINT ai_agent_memory_control_pkey;
ALTER TABLE platform.ai_agent_memory_control ADD CONSTRAINT pk_t_agent_memory_control
    PRIMARY KEY (tenant_id, member_id);

-- ============================================
-- 4. ai_agent_memory_extraction：claim 唯一约束含 tenant/member
-- ============================================

ALTER TABLE platform.ai_agent_memory_extraction ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE platform.ai_agent_memory_extraction ALTER COLUMN member_id  SET NOT NULL;
ALTER TABLE platform.ai_agent_memory_extraction ADD CONSTRAINT ck_t_agent_memory_extraction_tenant CHECK (btrim(tenant_id) <> '');

DROP INDEX uk_agent_memory_extraction_processing;
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_memory_extraction_tenant_processing
    ON platform.ai_agent_memory_extraction (tenant_id, member_id) WHERE status = 'PROCESSING';

-- ============================================
-- 5. 正式 run / event / outbox / usage / replay 结构
-- ============================================

-- 正式 run 表：P1 只读（run.get 经 TenantRunReadRepository），提交保持关闭。
CREATE TABLE IF NOT EXISTS platform.ai_run (
    tenant_id       VARCHAR(64)  NOT NULL,
    run_id          VARCHAR(64)  NOT NULL,
    member_id       VARCHAR(160) NOT NULL,
    action          VARCHAR(64)  NOT NULL,
    status          VARCHAR(16)  NOT NULL,
    policy_version  INTEGER      NOT NULL,
    acl_version     INTEGER      NOT NULL,
    resource_refs   JSONB,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, run_id),
    CONSTRAINT ck_ai_run_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_run_version CHECK (policy_version >= 1 AND acl_version >= 1)
);
CREATE INDEX IF NOT EXISTS idx_ai_run_member ON platform.ai_run (tenant_id, member_id, created_at);
COMMENT ON TABLE platform.ai_run IS '正式run：正式命名与归属；P1只读，提交/Worker仍关闭';

-- 事件：按 (tenant, run, seq) 读取，同域复合 FK；禁止裸 eventId 定位。
CREATE TABLE IF NOT EXISTS platform.ai_run_event (
    tenant_id   VARCHAR(64) NOT NULL,
    run_id      VARCHAR(64) NOT NULL,
    seq         BIGINT      NOT NULL,
    event_type  VARCHAR(32) NOT NULL,
    payload     JSONB,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, run_id, seq),
    CONSTRAINT ck_ai_run_event_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT fk_ai_run_event_run FOREIGN KEY (tenant_id, run_id)
        REFERENCES platform.ai_run (tenant_id, run_id)
);
COMMENT ON TABLE platform.ai_run_event IS '正式run事件：只读JSON分页按(tenant,run)+seq；P1不做SSE/seq生成';

-- outbox：P2 投递使用；表结构与归属现在定稿，消费侧保持关闭。
CREATE TABLE IF NOT EXISTS platform.outbox_event (
    tenant_id    VARCHAR(64) NOT NULL,
    event_id     VARCHAR(64) NOT NULL,
    run_id       VARCHAR(64) NOT NULL,
    event_type   VARCHAR(32) NOT NULL,
    payload      JSONB,
    state        VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at TIMESTAMPTZ,
    PRIMARY KEY (tenant_id, event_id),
    CONSTRAINT ck_outbox_event_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_outbox_event_state CHECK (state IN ('PENDING', 'PUBLISHED', 'FAILED'))
);
CREATE INDEX IF NOT EXISTS idx_outbox_event_state ON platform.outbox_event (state, created_at);

-- usage 账本：P2 计费/配额使用；P1 无写入路径。
CREATE TABLE IF NOT EXISTS platform.ai_usage_ledger (
    tenant_id  VARCHAR(64)  NOT NULL,
    ledger_id  VARCHAR(64)  NOT NULL,
    member_id  VARCHAR(160) NOT NULL,
    run_id     VARCHAR(64),
    feature    VARCHAR(64)  NOT NULL,
    quantity   BIGINT       NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, ledger_id),
    CONSTRAINT ck_ai_usage_ledger_tenant CHECK (btrim(tenant_id) <> '')
);
CREATE INDEX IF NOT EXISTS idx_ai_usage_ledger_member ON platform.ai_usage_ledger (tenant_id, member_id, created_at);

-- 委托 replay：生产 jti 消费账，原子 unique(issuer, jti)。
CREATE TABLE IF NOT EXISTS platform.ai_delegation_replay (
    issuer      VARCHAR(128) NOT NULL,
    jti         VARCHAR(64)  NOT NULL,
    tenant_id   VARCHAR(64)  NOT NULL,
    consumed_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at  TIMESTAMPTZ  NOT NULL,
    PRIMARY KEY (issuer, jti),
    CONSTRAINT ck_ai_delegation_replay_tenant CHECK (btrim(tenant_id) <> '')
);
CREATE INDEX IF NOT EXISTS idx_ai_delegation_replay_expiry ON platform.ai_delegation_replay (expires_at);
COMMENT ON TABLE platform.ai_delegation_replay IS '委托jti消费账：先验签后consume，重复jti 401';

-- ===== from V6__ai_tenant_barrier.sql =====
-- V6：AI 侧租户屏障状态（U10 强撤权协议）。
--
-- 与 platform V4 的 sys_ai_tenant_barrier 对应：platform 是政策变更的发起方，
-- AI 侧保存本节点可见的租户屏障状态，供 (a) /internal/ai/v1/authorization/barriers
-- 的 service 身份查询/关闭；(b) 高风险操作在登记 permit 前检查屏障。
--
-- 状态语义（与 05 §4.3 一致）：
--   OPEN     正常服务新 permit；
--   PENDING  drain 中：拒绝新 permit，等待活跃段退出；
--   CLOSED   撤权完成/受控关闭：拒绝新 permit；
--   UNKNOWN  节点失联或状态不可判定：保持关闭并要求处置，**不得凭租约过期推断成功**。
--
-- 不预置行：无行 = 从未设防（OPEN 语义由应用层显式判断，缺行不默认放行新 permit
-- 的路径必须由调用方写明；本表只为"已设防"提供事实）。

CREATE TABLE IF NOT EXISTS platform.ai_tenant_barrier (
    tenant_id          VARCHAR(64) NOT NULL PRIMARY KEY,
    status             VARCHAR(16) NOT NULL,
    barrier_id         VARCHAR(64),
    target_acl_version INTEGER,
    reason             VARCHAR(255),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_ai_tenant_barrier_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_tenant_barrier_status CHECK (status IN ('OPEN', 'PENDING', 'CLOSED', 'UNKNOWN'))
);
COMMENT ON TABLE platform.ai_tenant_barrier IS 'AI侧租户屏障：PENDING/CLOSED/UNKNOWN 拒绝新permit；UNKNOWN保持关闭直至可证实安全';

-- ===== from V7__derived_source_references.sql =====
-- Append-only provenance. NULL means unverified and must never enter model context or state restore.
DO $migration$
DECLARE target_table text;
BEGIN
  FOREACH target_table IN ARRAY ARRAY['ai_agent_memory','ai_agent_state','ai_conversation_summary','ai_agent_context_compaction']
  LOOP
    EXECUTE format('ALTER TABLE platform.%I ADD COLUMN source_refs jsonb, ADD COLUMN source_policy_version integer, ADD COLUMN source_acl_version integer', target_table);
    EXECUTE format('ALTER TABLE platform.%I ADD CONSTRAINT %I CHECK (source_policy_version IS NULL OR source_policy_version > 0)',target_table,target_table || '_source_pv_positive');
    EXECUTE format('ALTER TABLE platform.%I ADD CONSTRAINT %I CHECK (source_acl_version IS NULL OR source_acl_version > 0)',target_table,target_table || '_source_av_positive');
    EXECUTE format('ALTER TABLE platform.%I ADD CONSTRAINT %I CHECK (source_refs IS NULL OR jsonb_typeof(source_refs) = ''array'')',target_table,target_table || '_source_refs_array');
  END LOOP;
END
$migration$;

-- ===== from V8__run_execution_and_ingestion.sql =====
-- V8：P2 正式执行账本（受理/事件/outbox/步骤/预算/调用）与文档摄入（上传/版本/分块发布）。
--
-- 原则：
--  * 只新增列/表/索引/约束；不改 V1–V7，不重建历史行；P1 只读合成行必须保持可读。
--  * ai_run/ai_run_event/outbox_event/ai_usage_ledger 仍是唯一运行事实；本迁移只把
--    P2 执行所需字段补齐，不建第二套 run/event 事实。
--  * 新状态约束用 NOT VALID 添加：历史只读行不重查，但新写入必须满足。
--  * 向量维度物理固定在 1536（rag.default.dimension）；真实模型维度不同不得混写，
--    另立物理空间属后续迁移，运行期维度校验失败必须明确失败。
--
-- 归属守卫：所有新表 tenant_id 非空且非空串；同域复合 FK 指向 ai_run。

-- ============================================
-- 1. ai_run：正式执行账本扩展
-- ============================================

ALTER TABLE platform.ai_run ALTER COLUMN status TYPE VARCHAR(32);

ALTER TABLE platform.ai_run
    ADD COLUMN idempotency_key     VARCHAR(128),
    ADD COLUMN request_hash        VARCHAR(64),
    ADD COLUMN subject             VARCHAR(160),
    ADD COLUMN input               JSONB,
    ADD COLUMN budget              JSONB,
    ADD COLUMN execution_version   VARCHAR(64) NOT NULL DEFAULT 'p2-v1',
    ADD COLUMN version             BIGINT  NOT NULL DEFAULT 0,
    ADD COLUMN next_seq            BIGINT  NOT NULL DEFAULT 1,
    ADD COLUMN attempt             INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN fence               BIGINT  NOT NULL DEFAULT 0,
    ADD COLUMN lease_owner         VARCHAR(128),
    ADD COLUMN lease_until         TIMESTAMPTZ,
    ADD COLUMN terminal_result     JSONB,
    ADD COLUMN error_code          VARCHAR(64),
    ADD COLUMN retry_of            VARCHAR(64),
    ADD COLUMN cancel_requested_at TIMESTAMPTZ,
    ADD COLUMN started_at          TIMESTAMPTZ,
    ADD COLUMN finished_at         TIMESTAMPTZ;

ALTER TABLE platform.ai_run ADD CONSTRAINT ck_ai_run_version_counters
    CHECK (version >= 0 AND next_seq >= 1 AND attempt >= 0 AND fence >= 0) NOT VALID;

-- 幂等：同主体同动作同键唯一；不同主体/租户/动作互不干扰（不合并同名）。
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_run_idempotency
    ON platform.ai_run (tenant_id, subject, action, idempotency_key)
    WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_ai_run_claim ON platform.ai_run (status, lease_until, created_at);

ALTER TABLE platform.ai_run ADD CONSTRAINT ck_ai_run_status CHECK (status IN
    ('QUEUED','RUNNING','RETRY_WAIT','RECOVERING','WAITING_APPROVAL','NEEDS_RECONCILIATION',
     'CANCEL_REQUESTED','SUCCEEDED','FAILED','CANCELLED')) NOT VALID;

COMMENT ON COLUMN platform.ai_run.next_seq IS '该run可见事件下一seq；run行锁内递增，回滚不占号';
COMMENT ON COLUMN platform.ai_run.fence IS 'Worker租约代际；所有状态/步骤/事件/发布提交必须校验';

-- ============================================
-- 2. ai_run_event：稳定 eventId 与契约版本
-- ============================================

ALTER TABLE platform.ai_run_event ADD COLUMN event_id VARCHAR(64);
ALTER TABLE platform.ai_run_event ADD COLUMN schema_version INTEGER NOT NULL DEFAULT 1;

-- 历史只读行补确定性 eventId（不改变语义，只补稳定标识）。
UPDATE ai_run_event
   SET event_id = 'e-legacy-' || md5(tenant_id || ':' || run_id || ':' || seq)
 WHERE event_id IS NULL;

ALTER TABLE platform.ai_run_event ALTER COLUMN event_id SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_run_event_event_id ON platform.ai_run_event (event_id);
COMMENT ON COLUMN platform.ai_run_event.event_id IS '全局唯一事件ID，用于跨服务去重；seq是游标，eventId是去重键';

-- ============================================
-- 3. outbox_event：PG 持久投递任务
-- ============================================

ALTER TABLE platform.outbox_event
    ADD COLUMN attempt_count   INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    ADD COLUMN locked_by       VARCHAR(128),
    ADD COLUMN locked_until    TIMESTAMPTZ,
    ADD COLUMN last_error      VARCHAR(400),
    ADD COLUMN seq             BIGINT,
    ADD COLUMN schema_version  INTEGER NOT NULL DEFAULT 1;

ALTER TABLE platform.outbox_event DROP CONSTRAINT ck_outbox_event_state;
ALTER TABLE platform.outbox_event ADD CONSTRAINT ck_outbox_event_state
    CHECK (state IN ('PENDING','PUBLISHED','FAILED','DEAD_LETTER')) NOT VALID;

CREATE INDEX IF NOT EXISTS idx_outbox_event_claim ON platform.outbox_event (state, next_attempt_at);

-- ============================================
-- 4. ai_run_step：步骤检查点
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_run_step (
    tenant_id          VARCHAR(64) NOT NULL,
    run_id             VARCHAR(64) NOT NULL,
    step_id            VARCHAR(64) NOT NULL,
    attempt            INTEGER     NOT NULL,
    checkpoint_version INTEGER     NOT NULL DEFAULT 1,
    step_name          VARCHAR(64) NOT NULL,
    state              VARCHAR(24) NOT NULL,
    ref                JSONB,
    ref_hash           VARCHAR(64),
    usage              JSONB,
    fence              BIGINT      NOT NULL,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, run_id, step_id, attempt, checkpoint_version),
    CONSTRAINT ck_ai_run_step_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_run_step_state CHECK (state IN ('STARTED','COMPLETED','FAILED')),
    CONSTRAINT fk_ai_run_step_run FOREIGN KEY (tenant_id, run_id)
        REFERENCES platform.ai_run (tenant_id, run_id)
);
CREATE INDEX IF NOT EXISTS idx_ai_run_step_run ON platform.ai_run_step (tenant_id, run_id, attempt);
COMMENT ON TABLE platform.ai_run_step IS '步骤检查点：重复提交返回首次结果；提交必须校验当前fence';

-- ============================================
-- 5. 预算：租户上限 + 每 run 预占
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_tenant_budget (
    tenant_id   VARCHAR(64) NOT NULL,
    limit_units BIGINT      NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id),
    CONSTRAINT ck_ai_tenant_budget_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_tenant_budget_limit CHECK (limit_units >= 0)
);

CREATE TABLE IF NOT EXISTS platform.ai_budget_reservation (
    tenant_id      VARCHAR(64) NOT NULL,
    reservation_id VARCHAR(64) NOT NULL,
    run_id         VARCHAR(64) NOT NULL,
    member_id      VARCHAR(160) NOT NULL,
    units          BIGINT      NOT NULL,
    state          VARCHAR(16) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, reservation_id),
    CONSTRAINT uk_ai_budget_reservation_run UNIQUE (tenant_id, run_id),
    CONSTRAINT ck_ai_budget_reservation_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_budget_reservation_state CHECK (state IN ('RESERVED','SETTLED','RELEASED')),
    CONSTRAINT ck_ai_budget_reservation_units CHECK (units >= 0),
    CONSTRAINT fk_ai_budget_reservation_run FOREIGN KEY (tenant_id, run_id)
        REFERENCES platform.ai_run (tenant_id, run_id)
);
CREATE INDEX IF NOT EXISTS idx_ai_budget_reservation_state ON platform.ai_budget_reservation (tenant_id, state);

-- ============================================
-- 6. ai_model_call：模型/embedding 调用账（幂等结算）
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_model_call (
    tenant_id           VARCHAR(64) NOT NULL,
    call_id             VARCHAR(64) NOT NULL,
    run_id              VARCHAR(64) NOT NULL,
    attempt             INTEGER     NOT NULL,
    step_id             VARCHAR(64),
    kind                VARCHAR(24) NOT NULL,
    provider            VARCHAR(32) NOT NULL,
    model               VARCHAR(128),
    provider_request_id VARCHAR(160),
    request_hash        VARCHAR(64),
    usage_raw           JSONB,
    state               VARCHAR(24) NOT NULL,
    error_code          VARCHAR(64),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, call_id),
    CONSTRAINT ck_ai_model_call_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_model_call_kind CHECK (kind IN ('CHAT','EMBEDDING','RERANK')),
    CONSTRAINT ck_ai_model_call_state CHECK (state IN
        ('STARTED','SETTLED','FAILED','PENDING_RECONCILIATION','RELEASED')),
    CONSTRAINT fk_ai_model_call_run FOREIGN KEY (tenant_id, run_id)
        REFERENCES platform.ai_run (tenant_id, run_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_model_call_settlement
    ON platform.ai_model_call (tenant_id, run_id, provider_request_id, kind)
    WHERE provider_request_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ai_model_call_run ON platform.ai_model_call (tenant_id, run_id, created_at);

-- ============================================
-- 7. 文档/上传/版本/分块（P2 私有 PDF 摄入）
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_document (
    tenant_id            VARCHAR(64)  NOT NULL,
    doc_id               VARCHAR(64)  NOT NULL,
    kb_id                VARCHAR(64)  NOT NULL,
    name                 VARCHAR(255) NOT NULL,
    member_id            VARCHAR(160) NOT NULL,
    published_version_id VARCHAR(64),
    tombstoned_at        TIMESTAMPTZ,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, doc_id),
    CONSTRAINT ck_ai_document_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_document_name CHECK (btrim(name) <> '')
);
CREATE INDEX IF NOT EXISTS idx_ai_document_kb ON platform.ai_document (tenant_id, kb_id, created_at);

CREATE TABLE IF NOT EXISTS platform.ai_document_upload (
    tenant_id  VARCHAR(64)  NOT NULL,
    upload_id  VARCHAR(64)  NOT NULL,
    doc_id     VARCHAR(64),
    kb_id      VARCHAR(64)  NOT NULL,
    member_id  VARCHAR(160) NOT NULL,
    filename   VARCHAR(255) NOT NULL,
    mime_type  VARCHAR(128) NOT NULL,
    size_bytes BIGINT       NOT NULL,
    sha256     VARCHAR(64)  NOT NULL,
    object_key VARCHAR(512) NOT NULL,
    state      VARCHAR(16)  NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, upload_id),
    CONSTRAINT ck_ai_document_upload_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_document_upload_state CHECK (state IN ('STAGING','STORED','FAILED','DELETED')),
    CONSTRAINT ck_ai_document_upload_size CHECK (size_bytes >= 0)
);
CREATE INDEX IF NOT EXISTS idx_ai_document_upload_doc ON platform.ai_document_upload (tenant_id, doc_id);

CREATE TABLE IF NOT EXISTS platform.ai_document_version (
    tenant_id           VARCHAR(64) NOT NULL,
    version_id          VARCHAR(64) NOT NULL,
    doc_id              VARCHAR(64) NOT NULL,
    upload_id           VARCHAR(64) NOT NULL,
    run_id              VARCHAR(64),
    state               VARCHAR(24) NOT NULL,
    parse_ref           JSONB,
    chunk_count         INTEGER     NOT NULL DEFAULT 0,
    embedding_model     VARCHAR(128),
    embedding_dimension INTEGER,
    published_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, version_id),
    CONSTRAINT uk_ai_document_version_upload UNIQUE (tenant_id, doc_id, upload_id),
    CONSTRAINT ck_ai_document_version_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_document_version_state CHECK (state IN
        ('STAGING','PARSING','PARSED','CHUNKING','EMBEDDING','READY_TO_PUBLISH',
         'PUBLISHED','FAILED','SUPERSEDED','TOMBSTONED')),
    CONSTRAINT ck_ai_document_version_dimension CHECK (embedding_dimension IS NULL OR embedding_dimension > 0),
    CONSTRAINT fk_ai_document_version_doc FOREIGN KEY (tenant_id, doc_id)
        REFERENCES platform.ai_document (tenant_id, doc_id)
);
CREATE INDEX IF NOT EXISTS idx_ai_document_version_doc ON platform.ai_document_version (tenant_id, doc_id, created_at);

CREATE TABLE IF NOT EXISTS platform.ai_document_chunk (
    tenant_id       VARCHAR(64)  NOT NULL,
    version_id      VARCHAR(64)  NOT NULL,
    chunk_key       VARCHAR(160) NOT NULL,
    chunk_index     INTEGER      NOT NULL,
    doc_id          VARCHAR(64)  NOT NULL,
    kb_id           VARCHAR(64)  NOT NULL,
    content         TEXT         NOT NULL,
    content_hash    VARCHAR(64)  NOT NULL,
    char_count      INTEGER      NOT NULL,
    page_from       INTEGER,
    page_to         INTEGER,
    state           VARCHAR(16)  NOT NULL,
    embedding       vector(1536),
    embedding_model VARCHAR(128),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, version_id, chunk_key),
    CONSTRAINT ck_ai_document_chunk_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_document_chunk_state CHECK (state IN ('STAGING','PUBLISHED')),
    CONSTRAINT fk_ai_document_chunk_version FOREIGN KEY (tenant_id, version_id)
        REFERENCES platform.ai_document_version (tenant_id, version_id)
);
CREATE INDEX IF NOT EXISTS idx_ai_document_chunk_doc ON platform.ai_document_chunk (tenant_id, doc_id, version_id, chunk_index);
CREATE INDEX IF NOT EXISTS idx_ai_document_chunk_published ON platform.ai_document_chunk (tenant_id, state, version_id);
CREATE INDEX IF NOT EXISTS idx_ai_document_chunk_embedding ON platform.ai_document_chunk
    USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- ============================================
-- 8. 带引用回答的持久消息
-- ============================================

CREATE TABLE IF NOT EXISTS platform.ai_chat_message (
    tenant_id  VARCHAR(64)  NOT NULL,
    message_id VARCHAR(64)  NOT NULL,
    run_id     VARCHAR(64)  NOT NULL,
    sequence   INTEGER      NOT NULL,
    role       VARCHAR(16)  NOT NULL,
    content    TEXT,
    citations  JSONB,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, message_id),
    CONSTRAINT uk_ai_chat_message_seq UNIQUE (tenant_id, run_id, sequence),
    CONSTRAINT ck_ai_chat_message_tenant CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_ai_chat_message_role CHECK (role IN ('user','assistant')),
    CONSTRAINT fk_ai_chat_message_run FOREIGN KEY (tenant_id, run_id)
        REFERENCES platform.ai_run (tenant_id, run_id)
);

-- ===== from V9__upload_intents.sql =====
-- Private upload intent survives object-store/metadata/response crash windows.
CREATE TABLE IF NOT EXISTS platform.ai_upload_intent (
    tenant_id VARCHAR(64) NOT NULL CHECK (btrim(tenant_id) <> ''),
    member_id VARCHAR(160) NOT NULL CHECK (btrim(member_id) <> ''),
    idempotency_key VARCHAR(128) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    doc_id VARCHAR(64) NOT NULL,
    upload_id VARCHAR(64) NOT NULL,
    version_id VARCHAR(64) NOT NULL,
    object_key VARCHAR(512) NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'STAGING' CHECK (state IN ('STAGING','STORED','FAILED')),
    sha256 VARCHAR(64) NOT NULL,
    size_bytes BIGINT NOT NULL CHECK (size_bytes > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, member_id, idempotency_key),
    UNIQUE (tenant_id, upload_id)
);

-- ===== from V10__document_version_order.sql =====
-- New data P2 document versions: allocate a monotonic order under the document lock.
-- Historical V8 rows keep order zero; no historical migration or checksum is changed.
ALTER TABLE platform.ai_document ADD COLUMN version_counter BIGINT NOT NULL DEFAULT 0 CHECK(version_counter >= 0);
ALTER TABLE platform.ai_document_version ADD COLUMN version_order BIGINT NOT NULL DEFAULT 0 CHECK(version_order >= 0);
CREATE UNIQUE INDEX IF NOT EXISTS uk_document_version_order ON platform.ai_document_version(tenant_id,doc_id,version_order) WHERE version_order > 0;

-- ===== from V11__provider_spend_envelope.sql =====
-- A shared, conservative monetary envelope for one authorized execution.
CREATE TABLE IF NOT EXISTS platform.ai_provider_envelope (
 execution_id VARCHAR(128) PRIMARY KEY,
 cap_cny NUMERIC(12,6) NOT NULL CHECK(cap_cny>0 AND cap_cny<=20),
 reserved_cny NUMERIC(12,6) NOT NULL DEFAULT 0 CHECK(reserved_cny>=0 AND reserved_cny<=cap_cny),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS platform.ai_provider_spend (
 call_id VARCHAR(64) PRIMARY KEY,
 execution_id VARCHAR(128) NOT NULL REFERENCES platform.ai_provider_envelope(execution_id),
 provider VARCHAR(32) NOT NULL,
 model VARCHAR(64) NOT NULL,
 reserved_cny NUMERIC(12,6) NOT NULL CHECK(reserved_cny>0),
 provider_request_id VARCHAR(256),
 usage_raw JSONB,
 state VARCHAR(32) NOT NULL CHECK(state IN ('STARTED','RESPONSE_RECEIVED')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===== from V12__agent_action_ledgers.sql =====
-- P3 formal Agent ledgers. Same run/event/budget authority; legacy rows remain unclaimed.
ALTER TABLE platform.ai_run ADD CONSTRAINT uk_ai_run_member_ref UNIQUE (tenant_id,run_id,member_id);
CREATE TABLE IF NOT EXISTS platform.ai_agent_run (
 tenant_id varchar(64) NOT NULL, run_id varchar(64) NOT NULL, member_id varchar(160) NOT NULL,
 agent_version varchar(64) NOT NULL, engine_version varchar(64) NOT NULL, model varchar(64) NOT NULL,
 tool_catalog varchar(64) NOT NULL, checkpoint_version integer NOT NULL DEFAULT 1,
 max_steps integer NOT NULL CHECK(max_steps BETWEEN 1 AND 12), max_tool_calls integer NOT NULL CHECK(max_tool_calls BETWEEN 1 AND 12),
 max_tokens integer NOT NULL CHECK(max_tokens BETWEEN 1 AND 8192), steps_used integer NOT NULL DEFAULT 0,
 tools_used integer NOT NULL DEFAULT 0, tokens_used integer NOT NULL DEFAULT 0, source_refs jsonb NOT NULL,
 PRIMARY KEY(tenant_id,run_id), FOREIGN KEY(tenant_id,run_id,member_id) REFERENCES platform.ai_run(tenant_id,run_id,member_id),
 CHECK(btrim(tenant_id)<>'' AND steps_used BETWEEN 0 AND max_steps AND tools_used BETWEEN 0 AND max_tool_calls AND tokens_used BETWEEN 0 AND max_tokens)
);
CREATE TABLE IF NOT EXISTS platform.ai_agent_checkpoint (
 tenant_id varchar(64) NOT NULL, run_id varchar(64) NOT NULL, member_id varchar(160) NOT NULL, state_key varchar(128) NOT NULL,
 payload jsonb NOT NULL, payload_hash char(64) NOT NULL, attempt integer NOT NULL, fence bigint NOT NULL,
 engine_version varchar(64) NOT NULL, agent_version varchar(64) NOT NULL, model varchar(64) NOT NULL, tool_catalog varchar(64) NOT NULL,
 policy_version integer NOT NULL CHECK(policy_version>0), acl_version integer NOT NULL CHECK(acl_version>0),
 checkpoint_version integer NOT NULL CHECK(checkpoint_version=1), source_refs jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,run_id,state_key), FOREIGN KEY(tenant_id,run_id,member_id) REFERENCES platform.ai_run(tenant_id,run_id,member_id),
 CHECK(btrim(tenant_id)<>'' AND attempt>0 AND fence>0)
);
CREATE TABLE IF NOT EXISTS platform.ai_tool_call (
 tenant_id varchar(64) NOT NULL, action_id varchar(64) NOT NULL, member_id varchar(160) NOT NULL, run_id varchar(64) NOT NULL,
 tool_name varchar(64) NOT NULL, tool_version varchar(64) NOT NULL, args jsonb NOT NULL, args_hash char(64) NOT NULL,
 target varchar(160) NOT NULL, operation_key varchar(128) NOT NULL, approval_version integer NOT NULL DEFAULT 1,
 state varchar(32) NOT NULL CHECK(state IN('PROPOSED','APPROVED','REJECTED','STARTED','UNKNOWN','SUCCEEDED','INHERITED','CANCELLED')),
 permit_id varchar(128), permit_operation varchar(128), sender_stopped boolean NOT NULL DEFAULT false,
 result jsonb, source_refs jsonb NOT NULL DEFAULT '[]', provider_request_id varchar(128), external_id varchar(128),
 attempt integer NOT NULL, fence bigint NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,action_id), FOREIGN KEY(tenant_id,run_id,member_id) REFERENCES platform.ai_run(tenant_id,run_id,member_id),
 UNIQUE(tenant_id,member_id,tool_name,tool_version,target,operation_key), CHECK(btrim(tenant_id)<>'' AND attempt>0 AND fence>0 AND approval_version>0 AND version>0)
);
CREATE INDEX IF NOT EXISTS idx_ai_tool_call_run ON platform.ai_tool_call(tenant_id,run_id,created_at);
CREATE TABLE IF NOT EXISTS platform.ai_action_approval (
 tenant_id varchar(64) NOT NULL, action_id varchar(64) NOT NULL, approval_version integer NOT NULL,
 args_hash char(64) NOT NULL, tool_version varchar(64) NOT NULL, target varchar(160) NOT NULL, initiator_member varchar(160) NOT NULL,
 decision varchar(16) CHECK(decision IN('ALLOW','DENY')), decided_by varchar(160), decided_at timestamptz,
 expires_at timestamptz NOT NULL, policy_version integer NOT NULL CHECK(policy_version>0), acl_version integer NOT NULL CHECK(acl_version>0),
 PRIMARY KEY(tenant_id,action_id,approval_version), FOREIGN KEY(tenant_id,action_id) REFERENCES platform.ai_tool_call(tenant_id,action_id)
);
CREATE TABLE IF NOT EXISTS platform.ai_action_reconciliation (
 tenant_id varchar(64) NOT NULL, action_id varchar(64) NOT NULL, seq bigint NOT NULL, actor_member varchar(160) NOT NULL,
 evidence jsonb NOT NULL, evidence_hash char(64) NOT NULL, external_id varchar(128), finality varchar(16) NOT NULL CHECK(finality IN('FOUND','UNKNOWN')),
 policy_version integer NOT NULL, acl_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,action_id,seq), FOREIGN KEY(tenant_id,action_id) REFERENCES platform.ai_tool_call(tenant_id,action_id), CHECK(seq>0 AND policy_version>0 AND acl_version>0)
);
CREATE TABLE IF NOT EXISTS platform.ai_action_inheritance (
 tenant_id varchar(64) NOT NULL, new_run_id varchar(64) NOT NULL, source_run_id varchar(64) NOT NULL, source_action_id varchar(64) NOT NULL,
 member_id varchar(160) NOT NULL, args_hash char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,new_run_id,source_action_id), FOREIGN KEY(tenant_id,new_run_id,member_id) REFERENCES platform.ai_run(tenant_id,run_id,member_id),
 FOREIGN KEY(tenant_id,source_run_id,member_id) REFERENCES platform.ai_run(tenant_id,run_id,member_id), FOREIGN KEY(tenant_id,source_action_id) REFERENCES platform.ai_tool_call(tenant_id,action_id)
);
